# Parse the habit values and compute longest streak of "limited_screen_time_to_1_hr: yes"
streak = 0
max_streak = 0
for note in note_contents:
    content = note['content']
    # Find the line for limited_screen_time_to_1_hr
    for line in content.splitlines():
        if line.strip().startswith('limited_screen_time_to_1_hr:'):
            value = line.split(':', 1)[1].strip()
            if value == 'yes':
                streak += 1
                if streak > max_streak:
                    max_streak = streak
            else:
                streak = 0
            break
print(f"Longest streak: {max_streak} days")
apis.supervisor.complete_task(answer=max_streak)

